class Solution {
    int n;
    vector<int> memo;  // 0 unknown, 1 win, -1 lose

    bool dfs(int mask, int remaining) {
        if (memo[mask] != 0)
            return memo[mask] == 1;

        for (int i = 1; i <= n; ++i) {
            int bit = 1 << (i - 1);

            // Already used
            if (mask & bit)
                continue;

            // Case 1: Pick i and win immediately
            // Case 2: Pick i and put opponent in losing state
            if (i >= remaining ||
                !dfs(mask | bit, remaining - i)) {

                memo[mask] = 1;
                return true;
            }
        }

        memo[mask] = -1;
        return false;
    }

public:
    bool canIWin(int maxChoosableInteger, int desiredTotal) {
        n = maxChoosableInteger;

        if (desiredTotal <= 0)
            return true;

        if (n >= desiredTotal)
            return true;

        int sum = n * (n + 1) / 2;

        if (sum < desiredTotal)
            return false;

        memo.assign(1 << n, 0);

        return dfs(0, desiredTotal);
    }
};
